<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Category; use Illuminate\Http\Request; use Illuminate\Support\Str;
class CategoryController extends Controller { public function index(){return view('admin.categories.index',['categories'=>Category::latest()->paginate(20)]);} public function create(){return view('admin.categories.form',['category'=>new Category]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:255','is_active'=>'nullable']); Category::create(['name'=>$d['name'],'slug'=>Str::slug($d['name']),'is_active'=>$r->boolean('is_active')]); return redirect()->route('admin.categories.index')->with('success','Kategori eklendi.');} public function edit(Category $category){return view('admin.categories.form',compact('category'));} public function update(Request $r, Category $category){$d=$r->validate(['name'=>'required|max:255','is_active'=>'nullable']); $category->update(['name'=>$d['name'],'slug'=>Str::slug($d['name']),'is_active'=>$r->boolean('is_active')]); return redirect()->route('admin.categories.index')->with('success','Kategori güncellendi.');} public function destroy(Category $category){$category->delete(); return back()->with('success','Kategori silindi.');} public function show(Category $category){ return redirect()->route('admin.categories.edit',$category); } }
